export const staffScenarioSections = [
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">00</div><div><h2>The Staff+ response spine</h2><p>Structure a 3–5 minute answer so the interviewer can see your judgment and leverage.</p></div></div>\n      <div class=\"spine\">\n        <div><span>01</span><strong>Stakes</strong><p>Business impact, users, urgency, consequences.</p></div>\n        <div><span>02</span><strong>Constraints</strong><p>Scale, people, time, risk, regulation, legacy.</p></div>\n        <div><span>03</span><strong>Principles</strong><p>Decision criteria before products or solutions.</p></div>\n        <div><span>04</span><strong>Influence</strong><p>How disagreement and ownership were resolved.</p></div>\n        <div><span>05</span><strong>Execution</strong><p>Phases, guardrails, verification, rollback.</p></div>\n        <div><span>06</span><strong>Outcome</strong><p>Metrics, adoption, learning, lasting change.</p></div>\n      </div>\n      <div class=\"grid2\">\n        <article class=\"card\"><h3>Strong signals</h3><ul class=\"compact\"><li>You clarify what success means.</li><li>You quantify scale and risk.</li><li>You name credible alternatives.</li><li>You distinguish reversible and irreversible decisions.</li><li>You create mechanisms other teams can use.</li><li>You admit what failed and what changed.</li></ul></article>\n        <article class=\"card\"><h3>Weak signals</h3><ul class=\"compact\"><li>Starting with a favorite product.</li><li>Using “we” without explaining your role.</li><li>Heroics instead of repeatable mechanisms.</li><li>No stakeholder disagreement.</li><li>No measurable outcome.</li><li>A perfect ending with no learning.</li></ul></article>\n      </div>\n      <div class=\"callout\"><strong>Answer at two levels:</strong> the local technical decision and the system you created so future teams could make the decision safely without you.</div>\n    ",
    "id": "method",
    "title": "The Staff+ response spine"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">01</div><div><h2>Ambiguous executive mandate</h2><p>Tests framing, business translation, and architecture under uncertainty.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Strategy</span><span class=\"tag violet\">Influence</span></div><h3>“Build a unified data platform this year.”</h3><p class=\"prompt\">The CTO gives you the mandate, but business units disagree about the main problem. What do you do?</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Do not translate “platform” directly into infrastructure.</li><li>Interview representative producers and consumers; inventory pain by frequency and impact.</li><li>Define 2–3 measurable outcomes: onboarding time, freshness, incident rate, duplicated spend.</li><li>Identify shared capabilities versus domain-owned logic.</li><li>Select one thin vertical slice that proves the operating model.</li><li>Create a decision record and an explicit non-goal list.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would first turn the mandate into an outcome contract.</strong> I’d meet the highest-volume domains and classify problems into ingestion, quality, discovery, serving, and ownership. If onboarding time and inconsistent definitions dominate, I would not begin with a lakehouse migration. I’d propose a 90-day slice: one producer, two consumers, a paved ingestion path, contract checks, lineage, and an owned SLO. The steering group would agree on metrics and decision rights. At the end, we would either scale the pattern or revise it based on adoption and operating cost.</p><p class=\"redflag\"><strong>Red flag:</strong> promising a universal architecture before establishing shared outcomes.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> Who owns the roadmap? How do you stop the platform team becoming a ticket queue? What would make you cancel the initiative?</div>\n      </article>\n    ",
    "id": "ambiguity",
    "title": "Ambiguous executive mandate"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">02</div><div><h2>Large platform migration</h2><p>Tests sequencing, verification, organizational leverage, and risk retirement.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Architecture</span><span class=\"tag amber\">Execution</span></div><h3>200 pipelines must move to GCP</h3><p class=\"prompt\">The current Hadoop platform is expensive and reaches end of support in nine months. How do you lead the migration?</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Inventory pipelines by criticality, complexity, data sensitivity, and owner.</li><li>Define migration patterns: retire, lift/shift Spark, SQL rewrite, streaming redesign.</li><li>Create automated parity checks and dual-run criteria.</li><li>Build a migration factory: templates, docs, tooling, office hours, dashboard.</li><li>Migrate representative low-risk pipelines before crown jewels.</li><li>Make rollback and source-of-truth switching explicit.</li><li>Track decommission, not only new-platform deployment.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would treat this as a portfolio and operating-model change.</strong> First I’d classify the 200 pipelines and establish four standard landing patterns. The central team would own templates, automated reconciliation, and policy guardrails; domain owners would own business validation. Each pipeline would pass row-count, key, aggregate, freshness, and cost comparisons across a defined dual-run window. We would publish burn-up by risk class and block new features on the old platform after the first successful cohort. Success is not “200 jobs created”; it is validated traffic cutover, old compute removed, owners trained, and operating cost within target.</p><p class=\"redflag\"><strong>Red flag:</strong> treating every workload identically or leaving decommissioning until the end.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if parity never reaches 100%? How do you handle undocumented logic? Who accepts residual risk?</div>\n      </article>\n    ",
    "id": "migration",
    "title": "Large platform migration"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">03</div><div><h2>Standards without authority</h2><p>Tests influence, incentives, and platform-as-product thinking.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Influence</span><span class=\"tag\">Governance</span></div><h3>Every team builds pipelines differently</h3><p class=\"prompt\">You believe the company needs common reliability and security standards, but the teams do not report to you.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Start with recurring pain supported by incident or audit evidence.</li><li>Co-design minimum standards with respected engineers from each domain.</li><li>Separate mandatory controls from recommended patterns.</li><li>Make the compliant path easier: templates, libraries, CI checks, examples.</li><li>Use exceptions with owner, reason, expiry, and compensating control.</li><li>Measure adoption and support burden.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would not start with an architecture review board.</strong> I’d bring incident data showing the common failure modes, then form a small working group with domain representatives. We would define a minimum contract—ownership, lineage, idempotency, freshness SLO, sensitive-data classification—and ship a reference implementation plus CI checks. Controls required by regulation would be enforced; other conventions would earn adoption through reduced delivery time. Exceptions would be visible and time-bounded. My goal is a paved road that teams choose, with governance focused on risk rather than stylistic uniformity.</p><p class=\"redflag\"><strong>Red flag:</strong> using seniority as the adoption mechanism.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What must be centrally enforced? How do you handle a high-performing team that refuses? How do you avoid lowest-common-denominator standards?</div>\n      </article>\n    ",
    "id": "standards",
    "title": "Standards without authority"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">04</div><div><h2>Incorrect executive data</h2><p>Tests incident command, business communication, correctness, and systemic learning.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag amber\">Incident</span><span class=\"tag\">Data quality</span></div><h3>The dashboard is green—and wrong</h3><p class=\"prompt\">A CEO dashboard underreported revenue by 8% for six hours. Jobs succeeded and no system alert fired.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Declare a data incident and assign incident commander, technical lead, and communicator.</li><li>Label or disable untrusted outputs; notify decision makers with scope and next update.</li><li>Find the earliest broken invariant, not merely the failing table.</li><li>Choose replay, repair, or rollback based on traceability and blast radius.</li><li>Validate corrected data independently before restoring trust.</li><li>Postmortem across producer contract, pipeline checks, and consumer semantics.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>My first objective is to stop bad decisions, not to make the job green.</strong> I’d mark the dashboard degraded, state the known time window and affected metrics, and set a communication cadence. Technically, we would trace lineage backward and compare source totals, ingestion completeness, transformation invariants, and serving filters. After repair, an independent reconciliation must pass before the dashboard is relabeled trusted. The corrective actions would add business-level SLOs—completeness and reconciliation—not only task-success alerts, plus ownership and a runbook for withdrawing bad data.</p><p class=\"redflag\"><strong>Red flag:</strong> silently fixing the table without communicating loss of trust.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> Who may declare the data trustworthy again? How do you handle downstream extracts? Which SLO would have caught this?</div>\n      </article>\n    ",
    "id": "incident",
    "title": "Incorrect executive data"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">05</div><div><h2>Cost grew 3×</h2><p>Tests economics, prioritization, accountability, and performance tradeoffs.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">FinOps</span><span class=\"tag amber\">BigQuery</span></div><h3>BigQuery spend triples in one quarter</h3><p class=\"prompt\">The CFO asks for a 35% reduction without degrading critical reporting. What do you do?</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Attribute cost by workload, owner, environment, and business criticality.</li><li>Separate demand growth from regressions and waste.</li><li>Identify dominant levers: scans, concurrency, storage, refresh frequency, reservations.</li><li>Protect Tier-1 workloads with explicit SLOs and capacity isolation.</li><li>Apply fast reversible controls before architectural changes.</li><li>Make teams see marginal cost and savings.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would begin with a cost model, not blanket quotas.</strong> I’d break spend into the top jobs and consumers, then classify growth as valuable demand, inefficiency, or orphaned work. Immediate actions might include partition enforcement, eliminating full-refresh duplication, reducing excessive dashboard refresh, and killing unused scheduled queries. For sustained control, I’d introduce workload labels, budgets, reservation isolation for Tier-1 jobs, and cost checks in review. I would report savings alongside latency and freshness so we do not “save” money by violating the business SLA.</p><p class=\"redflag\"><strong>Red flag:</strong> optimizing many small jobs while ignoring the few workloads that dominate spend.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> On-demand or capacity pricing? How do you handle shared datasets? What if cost is driven by legitimate growth?</div>\n      </article>\n    ",
    "id": "cost",
    "title": "Cost grew 3×"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">06</div><div><h2>“Make it real time”</h2><p>Tests requirement challenge, product thinking, and complexity management.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Product</span><span class=\"tag\">Streaming</span></div><h3>A VP demands sub-second dashboards</h3><p class=\"prompt\">Current data arrives every 15 minutes. The proposed streaming redesign will double operating cost and add significant complexity.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Ask which decision changes within a second and who acts on it.</li><li>Translate “real time” into measurable freshness and end-to-end latency percentiles.</li><li>Separate alerting use cases from analytical dashboards.</li><li>Prototype the narrow high-value signal, not the full warehouse.</li><li>Present latency/correctness/cost/operability tradeoffs.</li><li>Define an exit condition if value is not demonstrated.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would challenge the requirement, not the stakeholder.</strong> I’d ask what action is blocked by 15-minute freshness. If the need is fraud intervention, I would create a streaming decision path for the minimal feature set while preserving batch reconciliation as the authoritative record. If the need is executive visibility, five-minute freshness may capture the value with far less state and on-call burden. I would present options with p95 latency, correctness semantics, cost, and staffing, then run a time-boxed experiment tied to a business metric.</p><p class=\"redflag\"><strong>Red flag:</strong> either saying “no” based on architecture preference or accepting sub-second latency without a value hypothesis.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> How do you maintain one metric definition across streaming and batch? When is Lambda architecture justified? Who owns 24/7 operations?</div>\n      </article>\n    ",
    "id": "realtime",
    "title": "“Make it real time”"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">07</div><div><h2>Breaking schema change</h2><p>Tests contracts, compatibility, producer/consumer ownership, and incident prevention.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Contracts</span><span class=\"tag amber\">Reliability</span></div><h3>A producer must change a critical event</h3><p class=\"prompt\">The checkout team needs to replace one field and change its meaning. Forty unknown consumers use the topic.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Discover consumers through registry, lineage, access logs, and communication.</li><li>Prefer additive versioning and a defined deprecation window.</li><li>Document semantic—not just syntactic—compatibility.</li><li>Publish dual fields/events and measure old-field consumption.</li><li>Provide test fixtures, contract validation, and migration examples.</li><li>Assign an explicit final removal owner and date.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would treat semantics as an API contract.</strong> We would introduce a new version or additive field, keep the old representation during a measured transition, and publish examples for edge cases. Registry compatibility checks prevent structural breakage, but we also need consumer validation because identical types can carry different meaning. We would track usage of the old contract, contact high-risk owners, and require an approved exception for consumers that miss the deadline. Removal happens only after telemetry and business-owner signoff—not after sending an email.</p><p class=\"redflag\"><strong>Red flag:</strong> relying solely on schema-registry compatibility to protect semantic meaning.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if consumers cannot be identified? How long is the compatibility window? Who pays the producer’s dual-publish cost?</div>\n      </article>\n    ",
    "id": "schema",
    "title": "Breaking schema change"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">08</div><div><h2>Principal-level technical conflict</h2><p>Tests intellectual honesty, decision mechanisms, and relationships after disagreement.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Influence</span><span class=\"tag\">Decision</span></div><h3>Two credible architectures, two strong advocates</h3><p class=\"prompt\">Another principal engineer wants a self-managed Kafka/Flink platform; you prefer managed GCP services. Teams are splitting into camps.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Make the decision criteria and constraints explicit together.</li><li>Steelman both options; separate facts from preferences.</li><li>Identify irreversible bets and assumptions that can be tested.</li><li>Use a small experiment only if it resolves a real uncertainty.</li><li>Choose a decision owner and deadline.</li><li>Record the decision and triggers for reconsideration.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would move the disagreement from people to criteria.</strong> Together we would score latency, ecosystem compatibility, operational staffing, failure recovery, portability, security, and three-year cost. Where evidence is weak—perhaps recovery time or connector compatibility—we would run a bounded spike. The designated owner makes the decision by a set date. Afterward, both of us communicate one direction, and the ADR records assumptions plus thresholds that would reopen it. Preserving the ability to collaborate is part of the outcome.</p><p class=\"redflag\"><strong>Red flag:</strong> escalating to executives before creating a fair technical decision process.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if you lose the decision? What if the chosen system later fails? How do you avoid endless experimentation?</div>\n      </article>\n    ",
    "id": "conflict",
    "title": "Principal-level technical conflict"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">09</div><div><h2>Build versus buy</h2><p>Tests total-cost thinking, differentiation, exit strategy, and vendor risk.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Strategy</span><span class=\"tag amber\">Economics</span></div><h3>Buy a data-quality platform or build internally?</h3><p class=\"prompt\">Engineering believes it can build the core in six months. A vendor can deploy in six weeks but creates recurring cost and lock-in.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Define which capability differentiates the business.</li><li>Estimate full lifecycle cost: development, integration, on-call, upgrades, adoption.</li><li>Test non-functional needs and exit/export capability.</li><li>Use representative workloads in a time-boxed proof.</li><li>Model switching cost, security review, pricing growth, and vendor viability.</li><li>Keep ownership of contracts, metadata, and policy semantics.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would compare capabilities and operating models, not license versus developer salary.</strong> We would define must-have checks, lineage integration, scale, APIs, security, and adoption workflow. The proof would use real high-volume datasets and include incident response and metadata export. If quality tooling is not differentiating, buying can be rational—provided contracts, results, and definitions remain portable. I would present three-year TCO, time-to-risk-reduction, and an exit plan. The decision would include a renewal review against adoption and avoided incidents.</p><p class=\"redflag\"><strong>Red flag:</strong> underestimating internal maintenance or assuming vendor adoption happens automatically.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> Which data must never leave GCP? How do you price future growth? What is your exit plan?</div>\n      </article>\n    ",
    "id": "buy",
    "title": "Build versus buy"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">10</div><div><h2>Platform not adopted</h2><p>Tests product sense, accountability, and willingness to change direction.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Platform product</span><span class=\"tag\">Leadership</span></div><h3>Your new paved road has 15% adoption</h3><p class=\"prompt\">The architecture is sound, but teams keep using older patterns. How do you respond?</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Observe actual onboarding; do not blame users.</li><li>Segment non-adoption: missing capability, migration cost, trust, incentives, documentation.</li><li>Measure time-to-first-value and support touchpoints.</li><li>Close the highest-friction gaps with design partners.</li><li>Offer migration tooling and clear ownership.</li><li>Mandate only when risk justifies it and a viable path exists.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>Low adoption means the platform has not earned product-market fit internally.</strong> I’d shadow two teams from first contact to production and quantify friction. If required features are missing, we fix the roadmap; if migration effort dominates, we build adapters and automated conversion; if trust is low, we publish SLOs and reference users. I would maintain a cohort funnel—discover, start, first production, retained use—and interview drop-offs. A mandate is appropriate for critical security controls, but not as a substitute for a usable product.</p><p class=\"redflag\"><strong>Red flag:</strong> interpreting resistance as an education problem before examining platform value.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> When would you retire the platform? Which adoption metric matters? How do you handle bespoke requirements?</div>\n      </article>\n    ",
    "id": "adoption",
    "title": "Platform not adopted"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">11</div><div><h2>Sensitive-data exposure risk</h2><p>Tests security partnership, containment, least privilege, and prevention.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Security</span><span class=\"tag amber\">Governance</span></div><h3>A broad service account can export customer PII</h3><p class=\"prompt\">No known exfiltration occurred, but the access path violates policy and may exist elsewhere.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Engage security and incident process; preserve audit evidence.</li><li>Contain with the least disruptive effective action.</li><li>Determine data, identities, destinations, and time window exposed.</li><li>Review logs for actual access/export and downstream copies.</li><li>Replace broad roles with workload-specific identity and boundaries.</li><li>Scan for the pattern organization-wide and prevent regression.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would handle this as a security finding with incident discipline.</strong> With security, we would preserve logs, restrict the principal, identify affected datasets and potential egress paths, and determine whether access was exercised. The durable fix is not simply removing one role: use workload identity, narrow dataset permissions, policy tags, VPC Service Controls where appropriate, and automated detection for equivalent grants. We would document business impact, notification obligations, and an owner for each corrective action.</p><p class=\"redflag\"><strong>Red flag:</strong> rotating a key and declaring the systemic issue solved.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if containment breaks production? What evidence proves no export occurred? Where would VPC-SC help—and not help?</div>\n      </article>\n    ",
    "id": "security",
    "title": "Sensitive-data exposure risk"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">12</div><div><h2>Multi-region resilience</h2><p>Tests business-driven reliability, data locality, and honest recovery design.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Reliability</span><span class=\"tag amber\">Architecture</span></div><h3>“The data platform must survive a regional outage”</h3><p class=\"prompt\">The requirement has no RTO/RPO and the current design uses regional datasets and pipelines.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Define business services, RTO, RPO, degraded mode, and decision authority.</li><li>Map every regional dependency and stateful control plane.</li><li>Separate ingestion durability, processing recovery, storage replication, and serving failover.</li><li>Consider data residency and cross-region cost.</li><li>Automate restoration and test through game days.</li><li>Be explicit about manual steps and unavailable features.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would refuse to equate “multi-region” with a recovery objective.</strong> We need to know which decisions must continue, acceptable data loss, and recovery time. I’d map regional dependencies, then design by tier: perhaps durable cross-region event retention, replicated critical datasets, reproducible infrastructure, and a read-only degraded dashboard before full pipeline recovery. The runbook must include identity, metadata, orchestration, DNS/clients, and validation—not only copied data. We prove the design through scheduled game days and measure actual RTO/RPO.</p><p class=\"redflag\"><strong>Red flag:</strong> assuming a multi-region storage location automatically makes the whole platform multi-region.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> Active/active or active/passive? How do you prevent split brain? Which workloads should not receive this investment?</div>\n      </article>\n    ",
    "id": "resilience",
    "title": "Multi-region resilience"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">13</div><div><h2>High-risk historical backfill</h2><p>Tests isolation, idempotency, validation, and production protection.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag\">Data correctness</span><span class=\"tag amber\">Operations</span></div><h3>Reprocess two years without hurting production</h3><p class=\"prompt\">A logic defect requires a full rebuild of a revenue model while live events continue.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Version the transformation and output; never overwrite trusted data first.</li><li>Snapshot inputs or define a reproducible source boundary.</li><li>Isolate compute quota, schedules, and write paths.</li><li>Process bounded partitions with checkpoints and restartability.</li><li>Validate row, key, aggregate, and business invariants.</li><li>Switch consumers atomically or through a controlled view.</li><li>Retain rollback and audit artifacts.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would make the backfill a separate versioned product.</strong> We would pin source snapshots and code, write to parallel partitioned tables, and throttle through a dedicated reservation so Tier-1 workloads retain capacity. Each batch is restartable and emits validation evidence. We would compare totals and representative records against the current model and source-of-truth finance controls. Consumers switch through a view only after signoff; rollback is changing the pointer, not rewriting two years again.</p><p class=\"redflag\"><strong>Red flag:</strong> running the revised job in place and depending on task retries for safety.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if source data changed since the original run? How do you reconcile with live updates? Who signs off?</div>\n      </article>\n    ",
    "id": "backfill",
    "title": "High-risk historical backfill"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">14</div><div><h2>Legacy decommission</h2><p>Tests change management, dependency discovery, incentives, and completion.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Change</span><span class=\"tag\">Migration</span></div><h3>Nobody wants to turn off the old warehouse</h3><p class=\"prompt\">The new platform is live, but teams distrust it and keep both systems running, doubling cost.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Build dependency telemetry rather than relying only on surveys.</li><li>Define parity and cutover criteria by workload tier.</li><li>Publish a freeze date for new development on legacy.</li><li>Provide consumer-specific migration support and comparison reports.</li><li>Use staged restrictions: read-only, scheduled shutdown windows, final removal.</li><li>Keep executive owner and savings visible.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>Decommissioning is a product milestone with owners, not cleanup.</strong> I’d combine query logs, credentials, schedules, and stakeholder mapping to identify remaining dependencies. Each critical consumer receives a parity report and cutover plan. We freeze new legacy development, then move through read-only and controlled outage rehearsals before final shutdown. Exceptions need an owner, business reason, and expiry. We track migrated consumers, unresolved dependencies, risk, and realized savings weekly.</p><p class=\"redflag\"><strong>Red flag:</strong> announcing a shutdown date without usage evidence or an exception process.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What if an unknown monthly job appears after shutdown? How long is rollback retained? Who can approve an exception?</div>\n      </article>\n    ",
    "id": "legacy",
    "title": "Legacy decommission"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">15</div><div><h2>Your initiative failed</h2><p>Tests accountability, learning speed, and whether your leadership improves after failure.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Self-awareness</span><span class=\"tag amber\">Learning</span></div><h3>Tell me about a platform decision you got wrong</h3><p class=\"prompt\">The interviewer wants more than a disguised success story.</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to answer</h4><ul><li>Choose a real decision where your judgment materially contributed.</li><li>State the incorrect assumption and why it seemed reasonable.</li><li>Explain the early signal you missed.</li><li>Describe how you communicated and limited further loss.</li><li>Show the changed mechanism, not only personal wisdom.</li><li>Quantify cost and recovery honestly.</li></ul></div>\n          <div class=\"answer\"><h4>Model response pattern</h4><p class=\"model\"><strong>I optimized for architectural consistency before validating migration cost.</strong> The target platform was technically sound, but I underestimated custom connectors and team retraining. Adoption stalled after the first cohort. I owned the miss, paused mandatory migration, and ran workflow studies with three domains. We narrowed the standard, added a compatibility path, and changed funding so the platform team owned conversion tooling. The delay cost one quarter, but adoption rose from X to Y and later standards required a representative migration before broad commitment. My lasting change was adding adoption and migration effort to architecture reviews.</p><p class=\"redflag\"><strong>Red flag:</strong> blaming stakeholders, or presenting a “failure” that had no negative consequence.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> When did you know? Why did you not stop sooner? What would your peers say you did poorly?</div>\n      </article>\n    ",
    "id": "failure",
    "title": "Your initiative failed"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">16</div><div><h2>Raise the technical bar</h2><p>Tests leverage through people, mechanisms, and inclusive technical leadership.</p></div></div>\n      <article class=\"scenario\">\n        <div class=\"scenario-top\"><div class=\"kicker\"><span class=\"tag violet\">Leadership</span><span class=\"tag\">Leverage</span></div><h3>Senior engineers depend on you for every architecture decision</h3><p class=\"prompt\">Quality is high, but you have become the bottleneck. How do you scale yourself?</p></div>\n        <div class=\"answer-grid\">\n          <div class=\"answer\"><h4 class=\"cyan\">How to reason</h4><ul><li>Identify recurring decisions that can become principles, examples, or automation.</li><li>Delegate decision ownership with bounded risk.</li><li>Coach through questions and written feedback, not answer substitution.</li><li>Create rotating design-review facilitation and shadowing.</li><li>Measure review latency and decision distribution.</li><li>Reserve direct involvement for irreversible/high-blast-radius choices.</li></ul></div>\n          <div class=\"answer\"><h4>Model response</h4><p class=\"model\"><strong>I would turn my judgment into mechanisms and grow new decision owners.</strong> I’d categorize reviews by risk, document principles and representative ADRs, and let senior engineers own medium-risk decisions with me as a coach. Review meetings would rotate facilitators and require proposals to state requirements, alternatives, and evidence. I would track how many decisions close without me, review lead time, and downstream reversals. The goal is not fewer standards; it is more people capable of applying them.</p><p class=\"redflag\"><strong>Red flag:</strong> solving the bottleneck by adding another approval committee.</p></div>\n        </div>\n        <div class=\"probe\"><strong>Likely probes:</strong> What decisions stay with you? How do you respond when a delegated decision is wrong? How do you mentor across reporting lines?</div>\n      </article>\n    ",
    "id": "talent",
    "title": "Raise the technical bar"
  },
  {
    "html": "\n      <div class=\"section-head\"><div class=\"num\">17</div><div><h2>Rapid-fire probes</h2><p>Practice answering each in 60–90 seconds, then invite deeper follow-up.</p></div></div>\n      <div class=\"table-wrap\"><table><thead><tr><th>Question</th><th>Your answer must reveal</th></tr></thead><tbody>\n        <tr><td>How do you know an architecture is successful?</td><td>Business outcome, technical SLO, adoption, cost, and operability.</td></tr>\n        <tr><td>When do you mandate a standard?</td><td>Risk threshold, usable paved road, exception policy, enforcement owner.</td></tr>\n        <tr><td>What belongs centrally versus in domains?</td><td>Economies of scale, consistency risk, local context, decision rights.</td></tr>\n        <tr><td>How do you prioritize technical debt?</td><td>Business exposure, change frequency, incident history, opportunity cost.</td></tr>\n        <tr><td>When should a data pipeline be rebuilt?</td><td>Migration cost, failure pattern, bounded rewrite, parity and rollback.</td></tr>\n        <tr><td>How do you handle an executive override?</td><td>Clear risk record, options, decision owner, commitment after decision.</td></tr>\n        <tr><td>What makes a data contract effective?</td><td>Semantics, ownership, compatibility, enforcement, observability, lifecycle.</td></tr>\n        <tr><td>How do you measure platform productivity?</td><td>Lead time, onboarding funnel, change failure, support burden, retention.</td></tr>\n        <tr><td>How much portability is enough?</td><td>Likely exit scenarios, abstraction cost, data/code portability, recovery plan.</td></tr>\n        <tr><td>How do you build trust after a data incident?</td><td>Transparency, independent validation, prevention, demonstrated reliability.</td></tr>\n      </tbody></table></div>\n      <h3 style=\"margin-top:1.5rem\">Final rehearsal checklist</h3>\n      <ul class=\"checklist\"><li>My role is explicit</li><li>Stakes are quantified</li><li>Constraints are credible</li><li>I name at least one alternative</li><li>Disagreement is visible</li><li>Execution is phased</li><li>Rollback or exit exists</li><li>Outcome has metrics</li><li>I acknowledge a tradeoff</li><li>I state what I learned</li><li>The mechanism scales beyond me</li><li>I can defend every detail</li></ul>\n      <div class=\"callout\"><strong>Best practice:</strong> write eight real stories from your career, map each story to two or three scenarios above, and rehearse multiple angles rather than memorizing sixteen separate answers.</div>\n    ",
    "id": "rapid",
    "title": "Rapid-fire probes"
  }
];
